#!/usr/bin/env bash
# Tags: no-fasttest
# no-fasttest: the fast test build has no Parquet support, and the fast test job does not check out `contrib/parquet-testing`.

# The files of https://github.com/apache/parquet-testing (the `contrib/parquet-testing` submodule) and
# https://github.com/apache/arrow-testing that pyarrow can read, compared with what pyarrow reads from them.
# `05359_parquet_testing_corpus` records what ClickHouse returns for every file of parquet-testing; this
# test checks those values against an independent implementation. The references are generated by
# `utils/data-lake-corpus/generate.py external`.

CUR_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
# shellcheck source=../shell_config.sh
. "$CUR_DIR"/../shell_config.sh

if [ ! -f "$CUR_DIR/../../../contrib/parquet-testing/README.md" ]
then
    echo "The Parquet test corpus is not found, run 'git submodule update --init contrib/parquet-testing'" >&2
    exit 1
fi

"$CUR_DIR"/data_lake_corpus/run_checks.sh "$CLICKHOUSE_LOCAL" "$CUR_DIR"/data_lake_corpus/checks_external.sql
